import type { Guide, GuideRelatedSummary } from "@/lib/types";
import { findDemoGuideCategory } from "@/lib/demo-data/guide-categories";

/**
 * "HVORDAN GJØR JEG DET?" – À TABLEs kunnskapsbibliotek for praktiske
 * kjøkkenteknikker og problemløsning. Startet som fire demo-/placeholder-
 * guider (spesifikasjon punkt 22) for å teste UI, søk, kategorier,
 * kort-svar, steg (inkl. tidtaker-felt), tips/pass på og relaterte guider.
 * Henrik bekreftet 27.08.2026 at de fire første ("Koke poteter", "Lage
 * roux", "Lage hvit saus", "Sausen er for tynn") er gode nok som ekte
 * innhold i seg selv – derfor isDemo: false på alle nå, og biblioteket er
 * utvidet med en større samling håndskrevne, faktabaserte tips/triks/
 * teknikk-guider på tvers av alle åtte kategoriene. Alt innhold her er
 * skrevet manuelt (ingen AI-generering, samme "deterministisk innhold"-
 * prinsipp som resten av demo-dataen), og seedes inn av scripts/seed.ts,
 * samme mønster som lib/demo-data/recipes.ts.
 *
 * Noen guider er koblet sammen via relatedGuides der det er en naturlig
 * kobling (f.eks. "Sausen har skilt seg" -> "Lage hollandaise", "La
 * kjøttet hvile" -> "Riktig kjernetemperatur på kjøtt") – kun i den
 * rekkefølgen guidene er definert her (en guide kan bare referere til en
 * guide definert FØR den selv i denne filen), se toRelated() under.
 */

const grunnteknikker = findDemoGuideCategory("grunnteknikker") ?? null;
const sauser = findDemoGuideCategory("sauser") ?? null;
