const smak = findDemoGuideCategory("smak") ?? null;
const reddeMaten = findDemoGuideCategory("redde-maten") ?? null;

function toRelated(guide: Guide): GuideRelatedSummary {
  return {
    id: guide.id,
    slug: guide.slug,
    title: guide.title,
    titleEn: guide.titleEn,
    category: guide.category,
    difficulty: guide.difficulty,
    estimatedTimeMinutes: guide.estimatedTimeMinutes,
    estimatedTimeMinutesMax: guide.estimatedTimeMinutesMax,
  };
}

